-- Hand-written (decision P0.7). Not generated by Drizzle Kit; policies are intentionally not declared in the Drizzle schema.
-- Runs as watheeq_owner.

ALTER TABLE audit_log ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE audit_log FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

-- audit_log is append-only: SELECT and INSERT within the current tenant. No UPDATE or DELETE policy.
CREATE POLICY audit_log_select ON audit_log FOR SELECT
  USING (tenant_id = app_current_tenant());
--> statement-breakpoint
CREATE POLICY audit_log_insert ON audit_log FOR INSERT
  WITH CHECK (tenant_id = app_current_tenant());
--> statement-breakpoint

-- INSERT and SELECT only. Without UPDATE or DELETE privileges the database rejects both (R0.10).
-- No sequence grant is needed: inserts into a GENERATED ALWAYS AS IDENTITY column do not check sequence privileges.
GRANT SELECT, INSERT ON audit_log TO watheeq_app;
